flowchart TD
    A["Suspected endocrine problem"] --> B{"Structural or functional?"}
    B -->|"STRUCTURAL — a mass"| C{"Benign or malignant?"}
    C --> D{"Does the enlargement itself<br/>cause clinical effects?"}
    D --> E["Mass effect:<br/>pituitary → optic chiasm, CN III/IV/VI, V1/V2<br/>thyroid → dysphagia"]
    B -->|"FUNCTIONAL — hormone"| F{"Too much or too little?"}
    F -->|"EXCESS"| G["Try to SUPPRESS it<br/>→ suppression test"]
    F -->|"DEFICIENCY"| H["Try to STIMULATE it<br/>→ stimulation test"]
    G --> I{"Primary, secondary/tertiary,<br/>or exogenous source?"}
    H --> I

flowchart TD
    A["T2DM inadequately controlled on metformin"] --> B{"Established ASCVD, HF, or CKD?"}
    B -->|Yes| C["SGLT2 inhibitor or GLP-1 RA<br/>cardiorenal benefit"]
    B -->|No| D{"Hypoglycemia a major concern?<br/>lives alone, drives, eats irregularly"}
    D -->|Yes| E["AVOID sulfonylureas and meglitinides<br/>→ DPP-4i, GLP-1 RA, SGLT2i"]
    D -->|No| F{"Weight a priority?"}
    F -->|"Needs to lose"| G["GLP-1 RA or SGLT2 inhibitor"]
    F -->|"Cachectic / underweight"| H["Avoid weight-losing agents"]
    E --> I{"Cost / oral only / adherence?"}
    G --> I
    I --> J["Weigh dosing frequency,<br/>injection vs oral, price"]
